pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed caller address that the fuzzer will supply
    function testFuzz_property(address caller) public {
        // keep wide but avoid zero address which is a common edge that may be special
        vm.assume(caller != address(0));

        // call owner() from arbitrary caller context
        address returned;
        vm.prank(caller);
        returned = c.owner();

        // The general property: reference always returns the stored owner (deployer == address(this) at construction)
        // therefore for ALL callers returned must equal the deployer (address(this) from setUp)
        assertTrue(returned == address(this));
    }
}

