pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address fuzzCaller) public {
        // keep fuzzed caller wide but not zero address to allow ownership to be non-zero
        vm.assume(fuzzCaller != address(0));

        // The reference contract sets owner to deployer (address(this) in setUp)
        // Call owner() as the fuzzer-supplied caller (no need to prank for view) and read the return
        bool ok;
        address reportedOwner;
        try c.owner{gas: gasleft()}() returns (address o) {
            ok = true;
            reportedOwner = o;
        } catch {
            ok = false;
            reportedOwner = address(0);
        }

        // The universal property: owner() must report the stored owner (which after construction is address(this)),
        // and thus must not be address(0). The mutant that always returns address(0) will fail this for some input.
        assertTrue(ok && reportedOwner != address(0));
    }
}

