pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // keep wide: allow any address
        // perform ownership transfer when newOwner is not zero to exercise transferOwnership
        if (newOwner != address(0)) {
            // only owner (this) can transfer
            c.transferOwnership(newOwner);
            // after transfer, owner() should return the stored owner (newOwner)
            // call owner() and check equality
            address reportedOwner = c.owner();
            assertTrue(reportedOwner == newOwner);
        } else {
            // if newOwner is zero we instead renounce ownership and expect owner() == address(0)
            c.renounceOwnership();
            address reportedOwner = c.owner();
            assertTrue(reportedOwner == address(0));
        }
    }
}

