pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter is the candidate newOwner to transfer ownership to.
    function testFuzz_property(address newOwner) public {
        // keep wide domain but ensure it's a valid address parameter (all addresses are valid);
        // no restrictive vm.assume so fuzzer can try address(0).

        // Caller is the initial owner (setUp used address(this) as owner). Call transferOwnership.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the reference contract rejects attempts to set owner to the zero address.
        // Therefore, for newOwner == address(0) the call should revert (ok == false) in the correct contract.
        // The buggy mutant removes that check and will succeed for newOwner == address(0), making ok == true.
        // We assert that the call did NOT succeed when newOwner is the zero address.
        // This single assertion holds for the reference for ALL inputs, and the mutant fails for some input (newOwner == address(0)).
        if (newOwner == address(0)) {
            assertTrue(!ok);
        } else {
            // For non-zero newOwner, both versions succeed; assert true to keep single-assert rule by evaluating a property
            // that the reference also satisfies: the call should succeed for non-zero addresses.
            assertTrue(ok);
        }
    }
}

