contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the newOwner address; if newOwner==address(0) the reference SHOULD revert and keep owner non-zero,
    // while the mutant will allow setting owner to address(0). We must be owner to call transferOwnership.
    function testFuzz_property(address newOwner) public {
        // keep domain wide
        // ensure msg.sender is current owner (setUp made address(this) the owner)
        // perform the call and observe whether owner() becomes zero
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: in the reference, it's impossible that after transferOwnership returns (ok==true)
        // owner() == address(0) because reference reverts when newOwner==address(0). Thus the property:
        // if the call succeeded, then owner() != address(0).
        // This holds for the correct contract for all inputs, but the mutant (which allows setting owner to zero)
        // will make this assertion fail for some fuzzed newOwner (specifically newOwner==address(0)).
        assertTrue(!(ok && c.owner() == address(0)));
