contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed: caller address that will invoke transferOwnership, and the newOwner address to transfer to.
    // GENERAL RULE: only the current owner (address(this) from constructor in setUp) can successfully call transferOwnership.
    // The mutant inverts onlyOwner, allowing non-owners to call transferOwnership; this test will fail on that mutant for some fuzz inputs.
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid the zero address for newOwner because transferOwnership in reference disallows zero address
        if (newOwner == address(0)) newOwner = address(1);

        // Determine expected success: only owner (which is address(this) set in constructor) should succeed
        bool expectedSucceeds = (caller == address(this));

        bool ok;
        // make the call as `caller` and catch revert to observe success
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: the correct contract satisfies that transferOwnership succeeds iff caller is owner.
        // On the mutant, some non-owner caller will succeed, causing this assertion to fail for some fuzz inputs.
        assertTrue(ok == expectedSucceeds);
    }
}

