pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameter: an arbitrary address candidate for calling transferOwnership
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid zero newOwner because transferOwnership in P requires non-zero
        vm.assume(newOwner != address(0));

        // owner at construction is address(this)
        address originalOwner = c.owner();
        assertTrue(originalOwner == address(this));

        bool ok;
        // try calling transferOwnership as the fuzzed caller
        // if caller == address(this) (the owner) the call should succeed on both P and M
        // if caller != owner then on correct contract it should revert; on mutant it may succeed
        if (caller == address(this)) {
            // owner invoking should succeed
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            // owner call must succeed on reference for all inputs
            assertTrue(ok);
            // and owner should be updated
            assertTrue(c.owner() == newOwner);
        } else {
            // non-owner invoking: on reference it MUST revert (so ok==false)
            vm.prank(caller);
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            // SINGLE assertion: reference guarantees non-owner cannot change owner, so call does not succeed
            // This holds for all inputs on reference, while mutant (with removed onlyOwner) will allow some callers to succeed
            assertTrue(!ok);
        }
    }
}

contract InvMutTest {
    C public c;
    event UpdatedRewardDistributor(address indexed distributor);

    constructor(C _c) { c = _c; }

    // Single external function that performs the minimal sequence and asserts the distinguishing property
    function run(address newDistributor) external {
        // require a non-zero distributor to make the difference observable (M sets zero regardless)
        require(newDistributor != address(0), "need non-zero distributor");

        // call the function under test (state-changing call must be top-level)
        c.setRewardDistributor(newDistributor);

        // observe public variable rewardDistributor via its autogenerated getter
        address observed = c.rewardDistributor();

        // The original contract sets rewardDistributor to the provided address, so they must match.
        // The mutant always sets it to zero, so this assertion will fail on the mutant.
        assert(observed == newDistributor);
    }

    // allow receiving ETH if needed by caller (not used here but harmless)
    receive() external payable {}
}
